package com.cinenest.payments.internal;

import java.util.*;
import com.cinenest.identity.ScopedAuthorization;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Service
class RefundService {
 private final RefundRepository db;private final BankRepository bank;private final LedgerRepository ledger;private final LedgerService finance;private final ScopedAuthorization auth;private final RefundPolicy policy;private final TransactionTemplate tx;
 RefundService(RefundRepository db,BankRepository bank,LedgerRepository ledger,LedgerService finance,ScopedAuthorization auth,RefundPolicy policy,PlatformTransactionManager manager){this.db=db;this.bank=bank;this.ledger=ledger;this.finance=finance;this.auth=auth;this.policy=policy;tx=new TransactionTemplate(manager);}
 private static UUID id(Object v){return BankService.id(v);}private static long n(Object v){return BankService.number(v);}
 private void eligible(UUID a,UUID owner){for(UUID principal:new TreeSet<>(List.of(a,owner)))if(!auth.eligible(principal,true))throw new BankFailure(403,"Current synthetic eligibility required");}
 private void permit(UUID a,UUID venue,String action){if(!auth.permits(a,venue,"refund.synthetic."+action,true))throw new BankFailure(403,"Current applicable refund grant required");}
 private static void require(boolean condition){if(!condition)throw new BankFailure(409,"Refund changed or operation unavailable");}
 Map<String,Object> request(UUID actor,UUID requestId,Map<String,Object> b){
  BankService.keys(b,"creditId","amountMinor","currency","expectedRevision","commandKey","reason");UUID credit=id(b.get("creditId")),key=id(b.get("commandKey"));long amount=RefundPolicy.amount(b.get("amountMinor"));String reason=LedgerService.text(b,"reason"),hash=BankPolicy.commandHash("REFUND_REQUEST:"+requestId,b);
  return tx.execute(s->{long ceiling=policy.ceiling();var r=bank.request(requestId,false).orElseThrow(()->new BankFailure(404,"Request not found"));if(!r.owner().equals(actor))throw new BankFailure(403,"Owned request required");eligible(actor,actor);var replay=db.replay(actor,key,hash);if(replay.isPresent())return replay.get();r=bank.request(requestId,true).orElseThrow();require(r.revision()==n(b.get("expectedRevision")));if(!"LKR".equals(b.get("currency"))||amount>ceiling)throw new BankFailure(400,"Synthetic currency/limit violation");var c=ledger.credit(Map.of("c",credit,"v",r.venue()),true);var matches=ledger.matchedRequest(Map.of("c",credit));require(matches.stream().anyMatch(m->rId(m).equals(requestId)));require("SYNTHETIC_BANK".equals(c.get("source_kind"))&&!finance.disputed(credit));if(!policy.originalPayer(c.get("fixture_key").toString()).equals(actor))throw new BankFailure(403,"Controlled original payer ownership required");require(amount<=n(c.get("amount_minor"))-finance.allocatedCredit(credit)-ledger.refundCommitted(Map.of("c",credit)));
   UUID refund=UUID.randomUUID();db.create(refund,credit,r.id(),actor,r.venue(),amount,policy.hash(),policy.snapshot());db.work(refund,"REVIEW_REQUIRED");audit(actor,r.venue(),refund,"REQUEST",reason,key);var out=view(refund,false);db.command(actor,key,hash,out);return out;});
 }
 private UUID rId(Map<String,Object> m){return (UUID)m.get("request_id");}
 Map<String,Object> command(UUID actor,UUID venue,UUID refund,UUID attempt,String action,Map<String,Object>b){
  String[] fields=switch(action){case "DESTINATION"->new String[]{"destinationReference","expectedRevision","commandKey","reason"};case "DECISION"->new String[]{"action","expectedRevision","commandKey","reason"};case "EVIDENCE","RECONCILE"->new String[]{"fixtureKey","expectedRevision","commandKey","reason"};default->new String[]{"expectedRevision","commandKey","reason"};};BankService.keys(b,fields);UUID key=id(b.get("commandKey"));String reason=LedgerService.text(b,"reason"),hash=BankPolicy.commandHash("REFUND:"+venue+":"+refund+":"+attempt+":"+action,b);
  return tx.execute(s->{policy.ceiling();var before=db.refund(refund,false);UUID owner=(UUID)before.get("owner_id");if(!venue.equals(before.get("venue_id")))throw new BankFailure(403,"Venue mismatch");eligible(actor,owner);if(owner.equals(actor))throw new BankFailure(403,"Own finance action denied");String capability=switch(action){case "DESTINATION"->"destination.verify";case "DECISION"->"review";case "ATTEMPT"->"execute";default->{var attempts=db.attempts(refund);yield !attempts.isEmpty()&&actor.equals(attempts.getLast().get("executor_id"))?"execute":"reconcile";}};permit(actor,venue,capability);
   // Replays re-check current eligibility/grants but never repeat a financial side effect.
   var replay=db.replay(actor,key,hash);if(replay.isPresent())return replay.get();
   bank.request((UUID)before.get("request_id"),true).orElseThrow();var credit=ledger.credit(Map.of("c",before.get("credit_id"),"v",venue),true);var r=db.refund(refund,true);require(n(r.get("revision"))==n(b.get("expectedRevision")));String state=r.get("state").toString();UUID approver=(UUID)r.get("approver_id");
   if(action.equals("DESTINATION")){
    require(state.equals("UNDER_REVIEW")&&db.destination(refund).isEmpty());String destination=policy.destination(credit.get("fixture_key").toString());if(!destination.equals(b.get("destinationReference")))throw new BankFailure(400,"Destination substitution rejected");db.destination(refund,destination,owner,actor,BankPolicy.hash(policy.hash()+":"+credit.get("movement_identity")+":"+destination));
    // Destination verification is append-only; advance revision without inventing a state.
    db.decision(refund,actor,"REVIEW",reason);
   }else if(action.equals("DECISION")){
    String choice=LedgerService.text(b,"action");switch(choice){
     case "REVIEW"->{require(state.equals("REQUESTED"));db.transition(refund,"UNDER_REVIEW",null);}
     case "APPROVE"->{permit(actor,venue,"approve");require(state.equals("UNDER_REVIEW")&&db.destination(refund).isPresent());require(n(r.get("amount_minor"))<=policy.ceiling()&&!finance.disputed((UUID)r.get("credit_id")));require(n(r.get("amount_minor"))<=n(credit.get("amount_minor"))-finance.allocatedCredit((UUID)r.get("credit_id"))-ledger.refundCommitted(Map.of("c",r.get("credit_id"))));db.transition(refund,"APPROVED",actor);}
     case "REJECT"->{require(Set.of("REQUESTED","UNDER_REVIEW").contains(state));db.transition(refund,"REJECTED",null);db.work(refund,"COMPLETE");}
     case "WITHDRAW"->{permit(actor,venue,"approve");require(Set.of("REQUESTED","UNDER_REVIEW","APPROVED","FAILED_CONFIRMED").contains(state));db.transition(refund,"WITHDRAWN",null);db.work(refund,"COMPLETE");}
     default->throw new BankFailure(400,"Review action required");
    }db.decision(refund,actor,choice,reason);
   }else if(action.equals("ATTEMPT")){
    require(Set.of("APPROVED","FAILED_CONFIRMED").contains(state)&&approver!=null&&!approver.equals(actor)&&!finance.disputed((UUID)r.get("credit_id")));var attempts=db.attempts(refund);UUID aid=UUID.randomUUID();db.attempt(aid,refund,attempts.size()+1,actor,key);db.transition(refund,"ATTEMPT_PREPARED",null);db.transition(refund,"AWAITING_EVIDENCE",null);db.work(refund,"OUTGOING_EVIDENCE_REQUIRED");
   }else{
    var attempts=db.attempts(refund);require(!attempts.isEmpty());var latest=attempts.getLast();UUID aid=(UUID)latest.get("attempt_id"),recorder=(UUID)latest.get("executor_id");if(action.equals("EVIDENCE"))require(aid.equals(attempt)&&state.equals("AWAITING_EVIDENCE"));else require(state.equals("UNKNOWN_RECONCILIATION_REQUIRED"));String fixture=LedgerService.text(b,"fixtureKey"),outcome=RefundPolicy.outcome(fixture);require(!action.equals("RECONCILE")||!outcome.equals("UNKNOWN_RECONCILIATION_REQUIRED"));var facts=db.evidence(aid);boolean recorded=facts.stream().anyMatch(e->fixture.equals(e.get("fixture_key"))&&"RECORDED".equals(e.get("phase")));String digest=BankPolicy.hash(aid+":"+fixture+":"+r.get("amount_minor")+":"+db.destination(refund).orElseThrow().get("manifest_hash"));
    if(actor.equals(recorder)){if(recorded)throw new BankFailure(403,"Outgoing recorder cannot verify completion");require(facts.stream().noneMatch(e->"RECORDED".equals(e.get("phase"))&&(!action.equals("RECONCILE")||!"SYNTHETIC-UNKNOWN".equals(e.get("fixture_key")))));db.evidence(aid,fixture,actor,null,digest);db.transition(refund,state,null);db.work(refund,"OUTGOING_VERIFICATION_REQUIRED");}
    else{require(recorded);db.evidence(aid,fixture,recorder,actor,digest);db.transition(refund,outcome,null);db.work(refund,switch(outcome){case "SIMULATED_CONFIRMED"->"COMPLETE";case "FAILED_CONFIRMED"->"FAILED_REVIEW_REQUIRED";default->"RECONCILIATION_REQUIRED";});}
   }
   audit(actor,venue,refund,action,reason,key);var out=view(refund,true);db.command(actor,key,hash,out);return out;
  });
 }
 private void audit(UUID a,UUID v,UUID r,String action,String reason,UUID key){finance.financialAudit(a,v,r,"REFUND_"+action,reason,key);}
 Map<String,Object> view(UUID id,boolean staff){var r=db.refund(id,false);var c=ledger.credit(Map.of("c",r.get("credit_id"),"v",r.get("venue_id")),false);var out=new LinkedHashMap<String,Object>();out.put("id",id.toString());out.put("requestId",r.get("request_id").toString());out.put("creditId",r.get("credit_id").toString());out.put("venueId",r.get("venue_id").toString());out.put("revision",n(r.get("revision")));out.put("state",r.get("state"));out.put("amountMinor",r.get("amount_minor").toString());out.put("approvedMinor",r.get("approver_id")==null?"0":r.get("amount_minor").toString());out.put("currency","LKR");out.put("availableMinor",finance.disputed((UUID)r.get("credit_id"))?"0":Long.toString(n(c.get("amount_minor"))-finance.allocatedCredit((UUID)r.get("credit_id"))-ledger.refundCommitted(Map.of("c",r.get("credit_id")))));out.put("destinationVerified",db.destination(id).isPresent());out.put("resolution",db.work(id).orElse("REVIEW_REQUIRED"));out.put("synthetic",true);out.put("realRepayment",false);out.put("label","SYNTHETIC REFUND TEST — NO REAL MONEY TRANSFERRED");out.put("decisions",db.decisions(id).stream().map(m->Map.of("action",m.get("action"),"at",LedgerService.instant(m.get("recorded_at")).toString())).toList());out.put("attempts",db.attempts(id).stream().map(m->Map.of("id",m.get("attempt_id").toString(),"sequence",m.get("sequence"),"evidence",db.evidence((UUID)m.get("attempt_id")).stream().map(e->Map.of("fixture",e.get("fixture_key"),"phase",e.get("phase"),"at",LedgerService.instant(e.get("recorded_at")).toString())).toList())).toList());if(staff){out.put("destinationReference",policy.destination(c.get("fixture_key").toString()));out.put("audit",db.audit(id).stream().map(m->Map.of("action",m.get("action"),"at",LedgerService.instant(m.get("recorded_at")).toString())).toList());}return out;}
 CustomerReads.Page<CustomerReads.Refund> ownedList(UUID actor,UUID request,int page,int size){CustomerReads.bounds(page,size);return tx.execute(s->{policy.ceiling();eligible(actor,actor);var parent=bank.request(request,true).orElseThrow(()->new BankFailure(404,"Request not found"));if(!parent.owner().equals(actor))throw new BankFailure(404,"Request not found");var rows=db.owned(request,actor,parent.venue(),page*size,size+1);var items=rows.stream().limit(size).map(id->{var r=db.refund(id,false);return new CustomerReads.Refund(id,request,parent.venue(),n(r.get("revision")),r.get("state").toString(),r.get("amount_minor").toString(),r.get("currency").toString(),db.work(id).orElse("REVIEW_REQUIRED"),true,false);}).toList();bank.audit(actor,request,"CUSTOMER_REFUNDS_READ","OWNED_SYNTHETIC_ONLY");return new CustomerReads.Page<>(items,page,size,rows.size()>size,bank.now().toString(),true);});}
 Object read(UUID actor,UUID venue,UUID id){return tx.execute(s->{policy.ceiling();if(id!=null){var r=db.refund(id,false);eligible(actor,(UUID)r.get("owner_id"));boolean staff=!actor.equals(r.get("owner_id"));if(staff)permit(actor,(UUID)r.get("venue_id"),"read");audit(actor,(UUID)r.get("venue_id"),id,"READ","SYNTHETIC_ONLY",UUID.randomUUID());return view(id,staff);}eligible(actor,actor);permit(actor,venue,"read");bank.audit(actor,null,"REFUND_QUEUE_READ","SYNTHETIC_ONLY");return db.queue(venue).stream().map(r->view(r,true)).toList();});}
}
